\begin{tikzpicture}[node distance=7mm and 6mm,
  scale=0.96, every node/.style={transform shape}]


\tikzset{
  box/.style   ={rounded corners, draw, align=left, inner sep=4pt,
                 text width=\MainW, minimum height=8mm},
  lemma/.style ={box}
}




\node[box] (setup) {Setup/Notation (Subsections~\ref{subsec:sHiggs}, \ref{subsec:ssH}, \ref{subsec:HNhiggs}, \ref{subsec:embL}):
\begin{itemize}\setlength\itemsep{0pt}
\item Consider quasi-compact open substacks $\mathcal{U}_{\circ}\subset\mathcal{U}\subset \Hig_G$ such that $\mathcal{S}=\mathcal{U}\setminus \mathcal{U}_{\circ}$ is a 
$\Theta$-stratum and $\mathcal{Z}$ is its center.
\item Consider a quasi-compact open substack $\mathcal{U}^L \subset \Hig_G^{L}$ for $\deg L \gg 0$
and a closed immersion $\mathcal{U} \hookrightarrow \mathcal{U}^L$.
\item There is a vector bundle $\mathcal{V}^L \to \mathcal{U}^L$ with a section $s^L$ such that 
$\mathcal{U}=(s^L)^{-1}(0)$.
\end{itemize}};

\node[box, below=of setup] (lemone) {$\Theta$-stratum of $(\mathcal{V}^L)^{\vee}$ (Subsection~\ref{subsec:ThetaH}): there is a $\Theta$-stratum $\mathcal{S}_{\mathcal{V}}\subset (\mathcal{V}^L)^{\vee}$ 
whose restriction to $\Omega_{\mathcal{U}}[-1]$ is a pull-back of $\mathcal{S}$.
We denote by $\mathcal{Z}_{\mathcal{V}}$ the center of $\mathcal{S}_{\mathcal{V}}$ and 
$(\mathcal{V}^L)_{\circ}^{\vee}$ the complement of $\mathcal{S}_{\mathcal{V}}$.
};

\node[box, below=of lemone] (lemtwo) {SOD of magic categories (Proposition~\ref{prop:sod:V}): construct a semiorthogonal decomposition 
\begin{align}\label{SOD:flow0}
\MM_{\mathbb{G}_m}((\V^L)^{\vee})_{\delta}=\langle\MM_{\mathbb{G}_m}(\zZ_{\V})_{\delta'}, \MM_{\mathbb{G}_m}((\V^L)^{\vee}_{\circ})_{\delta}\rangle. 
\end{align}
This is proved by reduction to a local model and using the result of Section~\ref{sec:magic}.
};

\node[box, below=of lemtwo] (lemthree) {SOD of limit categories (Proposition~\ref{prop:sod:KZ}): using the SOD for magic 
categories, construct a semiorthogonal decomposition 
\begin{align}\label{SOD:flow}
\LL(\mathcal{U})_{\delta}=\langle \LL(\mathcal{Z})_{\delta'}, j_{!}\LL(\mathcal{U}_{\circ})_{\delta}\rangle.
\end{align}
Here, $j_{!}$ is a fully-faithful left adjoint of the restriction functor 
$j^* \colon \LL(\mathcal{U})_{\delta}\to \LL(\mathcal{U}_{\circ})$.
};

\node[box, below=of lemthree] (lem4) {Proof of (\ref{SOD:flow}): using the Koszul equivalence, 
there is an equivalence 
\begin{align*}
    \Coh(\mathcal{U})\simeq \mathrm{MF}^{\mathrm{gr}}((\mathcal{V}^L)^{\vee}, f).
\end{align*}
The above equivalence restricts to an equivalence 
\begin{align*}
    \LL(\mathcal{U})_{\delta}\simeq \mathrm{MF}^{\mathrm{gr}}(\MM((\mathcal{V}^L)^{\vee})_{\delta\otimes (\omega_{\mathcal{U}^L})^{1/2}}, f).
\end{align*}
Then use (\ref{SOD:flow0}) to construct (\ref{SOD:flow}).};



\node[box, below=of lem4] (ded) {Proof of Theorem~\ref{thm:mainLG} (Subsection~\ref{subsec:proofofthm}): 
apply (\ref{SOD:flow}) to show that
\begin{align*}
	\IndL(\Hig_G(\chi))_w \simeq \colim_{\mu \in N(T)_{\mathbb{Q}+}} \IndL(\Hig_G(\chi)_{\preceq \mu})_w.
\end{align*}
It gives a compact generation of $\IndL(\Hig_G(\chi))_w$ and the subcategory of 
compact object is 
\begin{align*}
    \LL(\Hig_G(\chi))_w \simeq \colim_{\mu \in N(T)_{\mathbb{Q}+}} \LL(\Hig_G(\chi)_{\preceq \mu})_w.
\end{align*}
By applying (\ref{SOD:flow}) again, we obtain Theorem~\ref{thm:mainLG}.
};



\draw[->] (setup) -- (lemone);
\draw[->] (lemone) -- (lemtwo);
\draw[->] (lemtwo) -- (lemthree);
\draw[->] (lemthree) -- (lem4);
\draw[->] (lem4) -- (ded);

\end{tikzpicture}
\caption{Flowchart of the proof of Theorem~\ref{thm:mainLG}}\label{fig:flow}
\end{figure}

